var tokNew = '{' + '{' + 'product.coffee-machine.available_pieces' + '}' + '}';
if (!output.includes(tokOld) && !output.includes(tokNew))
  return { pass: false, score: 0, reason: 'did not use an availability/stock-count placeholder' };
return { pass: true, score: 1, reason: 'used an availability/stock-count placeholder' };

